('16a49cdd-36eb-4795-ba90-9a79d8ea4e03', '21feff02-016d-46e2-bb9d-c27495133b1b', '22. óra: Többszörös, közös többszörös', 'Közös többszörösök, legkisebb közös többszörös (lkkt) és közös nevező.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "c1423a36-6864-4167-a272-8a2bd46c9d6b", "text": "Mit jelent két szám legkisebb közös többszöröse (lkkt)?", "type": "multiple-choice", "options": [{"id": "0b631e57-3b9b-4373-b91e-151300499010", "text": "A legkisebb olyan pozitív számot, amely mindkét számmal osztható", "isCorrect": true}, {"id": "e37306c9-d1cf-47f7-bd8a-86d3c10c2f69", "text": "A két szám szorzatát mindig", "isCorrect": false}, {"id": "4f9f21bc-6afc-425f-a7ac-bd22a2d533ac", "text": "A legkisebb osztót", "isCorrect": false}, {"id": "1e95b1e4-f9b4-43d0-aedb-6052fc4f98cb", "text": "A két szám különbségét", "isCorrect": false}], "timeLimit": 15}, {"id": "b63bbc95-f468-4b3c-88f6-af83c0fe5ce5", "text": "Mennyi a 4 és 6 legkisebb közös többszöröse, lkkt(4, 6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "d0d58b47-a2ee-45b9-8caf-af53b08d0609", "text": "Mennyi a 3 és 5 legkisebb közös többszöröse, lkkt(3, 5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "5e2506d6-345a-4a40-99d4-a93653935ca6", "text": "Relatív prímek (pl. 3 és 5) legkisebb közös többszöröse a két szám szorzata.", "type": "true-false", "options": [{"id": "b385f657-ec4f-4f8e-9d6b-5558686a37d1", "text": "Igaz", "isCorrect": true}, {"id": "86a4e870-3ecf-41e9-891d-33ea774f97d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2e946ef4-73ee-4944-9d78-a9355d4dd3d7", "text": "A közös többszöröst használjuk törtek közös nevezőre hozásakor.", "type": "true-false", "options": [{"id": "a581f99a-e764-4ad7-b516-35d11d20452e", "text": "Igaz", "isCorrect": true}, {"id": "47b123f8-0042-4a55-b646-4ec89062aa2e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "33a48163-133d-4256-abf7-6ad8ae