('d35731e7-9695-45be-86b3-c20412950686', '21feff02-016d-46e2-bb9d-c27495133b1b', '26. óra: Témazáró dolgozat', 'Témazáró számonkérés az Egész számok és oszthatóság témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "1691a3d4-20c3-4222-a91e-f739d71b36a8", "text": "1. Mennyi (-18) + (+30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "ce2799ca-8a7d-44e6-b20c-88fdc0d900cb", "text": "2. Mennyi (-7) * (-9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "63"}, {"id": "cfe5fcb9-c25a-430e-814c-76e0f9c0935a", "text": "3. Mennyi (-72) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "bf7f13e1-61fe-4fbf-b264-7efd852cd76f", "text": "4. Osztható-e a 534 3-mal?", "type": "true-false", "options": [{"id": "70a0bb89-23c3-43a6-8b45-a3a479d84945", "text": "Igaz (5+3+4=12)", "isCorrect": true}, {"id": "eac5160d-fa97-406b-b2d3-e7aac1f91b3c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9d220cc8-4757-41dd-ae78-d92311d6e0d6", "text": "5. Osztható-e a 620 4-gyel?", "type": "true-false", "options": [{"id": "7916c1b3-5148-44c2-80de-446c6dff4170", "text": "Igaz (20 osztható 4-gyel)", "isCorrect": true}, {"id": "8d189787-6c6b-4c25-88d2-360093f84ce5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "458aef24-35b5-46ec-9454-6330668f4c28", "text": "6. Mennyi lkkt(6, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "0b6541c7-2c15-4449-9c96-7c4533fc039f", "text": "7. Mennyi lnko(18, 24)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "9f7ebcb8-44cc-45ba-af07-796599cc2b0c", "text": "8. Hány prímszám van 1 és 10 között? (2, 3, 5, 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "17ad2626-5c0e-4224-8589-f001484a141b", "text": "9. Hányféleképpen ülhet le 3 gyermek 3 székre?", "type": "text-inpu