('06009c60-e8b0-4d29-8d8d-eb033be965e1', '21feff02-016d-46e2-bb9d-c27495133b1b', '27. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése, hibák elemzése, tapasztalatok összegzése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "a33a0054-1f43-4ede-bca3-5289f25d0f31", "text": "Mi volt a leggyakoribb hiba az előjelszabályok alkalmazásakor?", "type": "multiple-choice", "options": [{"id": "9c8bd775-9ff7-43b7-9202-c2ce27df58d9", "text": "A szorzás/osztás és összeadás előjelszabályainak összetévesztése", "isCorrect": true}, {"id": "26537012-32a2-491a-b576-cd0e0d8e1bb1", "text": "A számok leírása", "isCorrect": false}, {"id": "7742fdae-9fea-4d66-9c96-24aebe0badb3", "text": "A vonalzó használata", "isCorrect": false}, {"id": "df05cdf3-413c-48e5-a332-c939f73de896", "text": "A válasz elhagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "ac71379a-5229-4e83-b481-1b417d3f5bf7", "text": "Az osztási szabályok (pl. 3-mal, 9-cel) esetén a számjegyek összege a döntő.", "type": "true-false", "options": [{"id": "b6e82365-d543-4b58-8e7a-ee77acd15993", "text": "Igaz", "isCorrect": true}, {"id": "72762015-7395-45e1-88a8-e5bf5cdef1f2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3ed73f93-bc9b-40c4-bb78-8eada697766e", "text": "Mennyi (-5) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "8bbf892e-084f-47ab-b66f-a6c5e2200eb4", "text": "A lkkt meghatározásánál a többszörösök közül a legkisebbet választjuk.", "type": "true-false", "options": [{"id": "905269ae-cfc1-474c-bbc7-39305d145338", "text": "Igaz", "isCorrect": true}, {"id": "3cafcca8-7353-4d37-af0c-0c48499ba83c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56b46c82-3401-4580-9c62-dd6d0b195352", "text": "Mennyi (-30) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "bf4064e0-7b56-47d9-a293-f69a687a54e3", "text": "A dolgozatok áttekintése segít a hiányosságok pótl