('2be95136-315b-4949-bf6a-8ae58d02a25b', '21feff02-016d-46e2-bb9d-c27495133b1b', '28. óra: Mit tanultunk a törtekről? Ismétlés', 'Ötödikben tanult ismeretek: közönséges tört értelmezése, számláló, nevező, bővítés, egyszerűsítés.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "b8a88218-5520-4faa-8f2d-0df7650655db", "text": "Mi a közönséges tört felső száma?", "type": "multiple-choice", "options": [{"id": "aa34529a-f29f-4946-b01c-2a49afbf6f0b", "text": "Számláló", "isCorrect": true}, {"id": "3195ba08-fd23-460f-aab6-5b48ac9ee797", "text": "Nevező", "isCorrect": false}, {"id": "83f5acc1-eff4-4c3a-9fb5-2646ee57a09c", "text": "Törtvonal", "isCorrect": false}, {"id": "d30b5de1-c0e1-4887-91fa-2173d52f2fe9", "text": "Egész rész", "isCorrect": false}], "timeLimit": 15}, {"id": "f7855b37-ffa8-4bbc-9672-257933242e09", "text": "Mi a közönséges tört alsó száma?", "type": "multiple-choice", "options": [{"id": "840f36ad-d704-432d-ac03-141ebb53240a", "text": "Nevező", "isCorrect": true}, {"id": "4192a3d0-3672-4af9-981b-2593fe3a735b", "text": "Számláló", "isCorrect": false}, {"id": "5839db75-812d-433f-9ecb-f9f63ecabe55", "text": "Osztó", "isCorrect": false}, {"id": "8fe93d17-2f38-4178-8487-d97c7071c6d7", "text": "Különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "07718e12-1e53-4e4f-9970-7898139af364", "text": "Mennyi a 3/4 bővítve 2-vel?", "type": "multiple-choice", "options": [{"id": "eed1ceaa-d203-4250-b191-2c2d400ebc48", "text": "6/8", "isCorrect": true}, {"id": "87057e09-b8c2-49a1-bf80-ae96ccb359ec", "text": "5/6", "isCorrect": false}, {"id": "8305d3bd-24e6-4229-8592-675a9a88699e", "text": "3/8", "isCorrect": false}, {"id": "a38ba853-ec40-47d3-8684-51c067d4d1ce", "text": "6/4", "isCorrect": false}], "timeLimit": 15}, {"id": "092aae88-07cb-471e-af3c-289f0d46d205", "text": "Mennyi a 6/10 egyszerűsítve 2-vel?", "type": "multiple-choice", "options": [{"id": "e784720d-199a-4e6f-86b4-7d5b8831a090", "text": "3/5", "isCorrect": true}, {"id": "cbd34297-617a-4369-8e6e-2e39906a4361", "text": "3/10", "isCorrect": false}, {"id": "275b48a6-d6cf-49ab-8b29-6f9bb434542b", "text": "6/5", "isCorrect": false}, {"id": "8853eb37-10fa-46b3-8597-94aad3d90503", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "2e54b002-b74d-423e-b8f7-762ebb6f3f16", "text": "A tört értéke nem változik, ha számlálóját és nevezőjét ugyanazzal a nem-nulla számmal szorozzuk (bővítjük).", "type": "true-false", "options": [{"id": "89983567-b97f-4611-b1b2-65acc298f935", "text": "Igaz", "isCorrect": true}, {"id": "974853a2-dd20-4c01-9033-bde33eafbb36", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0ce1f2ef-c3fd-408b-8af7-1ab42bd9402f", "text": "Hány negyedből áll 1 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "ec0e6d0a-878e-47af-a714-cac50c79421d", "text": "Mennyi 1/2 + 1/4?", "type": "multiple-choice", "options": [{"id": "f80583fa-a791-44b8-8c01-3037ed76e544", "text": "3/4 (2/4 + 1/4)", "isCorrect": true}, {"id": "4802572c-4002-49b2-9ac1-d56c1039c0dd", "text": "2/6", "isCorrect": false}, {"id": "7835d1fb-bbb0-439f-8b73-48c8eb31c381", "text": "2/4", "isCorrect": false}, {"id": "f8ee4bb6-c106-43a3-b90f-0b057269e699", "text": "1/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('ea511a88-8e5a-4f28-9cc1-110b74ff8e2f', '21feff02-016d-46e2-bb9d-c27495133b1b', '29. óra: Mit tanultunk a törtekről? Ismétlés II.', 'Összeadás és kivonás azonos és különböző nevezőjű törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "40acaa92-a84e-4a14-8764-cfdb83e3aa3b", "text": "Hogyan adjuk össze a különböző nevezőjű törteket?", "type": "multiple-choice", "options": [{"id": "57c16f62-43a7-4420-9a0e-b5e2da9bc04d", "text": "Közös nevezőre hozzuk őket, majd a számlálókat összeadjuk", "isCorrect": true}, {"id": "cefe7ae9-fbb9-4fd4-b883-e2b2891970be", "text": "A számlálókat és nevezőket is összeadjuk", "isCorrect": false}, {"id": "23e3d15b-5435-4235-a172-8e125b46353d", "text": "A számlálókat megszorozzuk", "isCorrect": false}, {"id": "b7663168-6cea-49d9-ac22-7ee60aa495f3", "text": "Nem lehet összeadni őket", "isCorrect": false}], "timeLimit": 15}, {"id": "504d7f28-5e12-4fb4-8f01-32b315ffa354", "text": "Mennyi 1/3 + 1/6? (2/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "d6eb85f8-a559-4769-a262-9d6f9ed8c12b", "text": "3/6 (azaz 1/2)", "isCorrect": true}, {"id": "8590f432-dcfd-40a2-ae06-7e7cc68b3f5b", "text": "2/9", "isCorrect": false}, {"id": "8cef5818-2b58-4404-a51a-536606d3a98d", "text": "1/9", "isCorrect": false}, {"id": "1d41971b-ea2c-4255-8ec3-ea2579d9276e", "text": "2/6", "isCorrect": false}], "timeLimit": 15}, {"id": "c590bd06-3cb4-49f0-abbf-86ae1ac2cfe6", "text": "Mennyi 5/8 - 3/8?", "type": "multiple-choice", "options": [{"id": "638d501c-7142-40d9-9b02-24ae27ed8642", "text": "2/8 (azaz 1/4)", "isCorrect": true}, {"id": "61a4b746-0213-4a23-b7cc-b497f977d84c", "text": "2/0", "isCorrect": false}, {"id": "5466b45a-8e9c-4005-bf78-9ede6857c8a2", "text": "8/8", "isCorrect": false}, {"id": "4498809c-45c0-4825-8cd2-660520f8f1bc", "text": "1/8", "isCorrect": false}], "timeLimit": 15}, {"id": "d853383a-6dd3-4cb7-a288-766d9012b268", "text": "Az 1/2 és 2/4 egyenlő értékű törtek.", "type": "true-false", "options": [{"id": "14e836b3-9f65-4961-a466-0d80dc