('824992b5-830d-4054-9252-12e3de537494', '21feff02-016d-46e2-bb9d-c27495133b1b', '30. óra: Szorzás törttel, a reciprok', 'Tört szorzása törttel, reciprok fogalma.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "dcd8880d-50d9-4edb-823d-6b1aaaa2d35c", "text": "Hogyan szorzunk törttel törtet?", "type": "multiple-choice", "options": [{"id": "c16bb6ca-d902-4904-aae0-44c5f61e995a", "text": "A számlálót a számlálóval, a nevezőt a nevezővel szorozzuk", "isCorrect": true}, {"id": "24ebe7b9-22e7-429c-9c21-9f9e79069902", "text": "Közös nevezőre hozzuk őket", "isCorrect": false}, {"id": "295bfec7-f949-4be1-9a6b-cddc993eb231", "text": "A számlálót a nevezővel szorozzuk", "isCorrect": false}, {"id": "cbea3dba-e7c5-4a31-b9e3-3bdca616a9a9", "text": "Keresztbe szorzunk", "isCorrect": false}], "timeLimit": 15}, {"id": "64ff9da6-faa8-4424-8665-da324b3aee02", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "b480367c-f629-4820-a791-42b54093cccd", "text": "6/15 (azaz 2/5)", "isCorrect": true}, {"id": "c4e7c06b-f091-421b-9c5f-22bbd7ba98d6", "text": "5/8", "isCorrect": false}, {"id": "75bf0270-7ca2-44cf-88b6-a95e5bb91181", "text": "6/8", "isCorrect": false}, {"id": "cb57c35d-c78a-4673-b00d-3da90462d0d7", "text": "2/15", "isCorrect": false}], "timeLimit": 15}, {"id": "2f58e49c-6ee3-43fb-b217-9b253102c0db", "text": "Mi a 3/4 reciproka?", "type": "multiple-choice", "options": [{"id": "92eefb13-07f6-4ed0-ab0f-c90145b8b5ce", "text": "4/3", "isCorrect": true}, {"id": "75cd7e45-c62d-40d4-b046-6d8b3fc7da89", "text": "-3/4", "isCorrect": false}, {"id": "32a0dc2d-5f7f-4928-8133-84b06442c1ab", "text": "1/4", "isCorrect": false}, {"id": "8bf774cb-4c95-4876-924e-41e5df27eb29", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "5e89759b-3401-4dd6-9d49-f6518e804766", "text": "Egy szám és a reciproka szorzata mindig 1.", "type": "true-false", "options": [{"id": "353b19a0-adf6-48d9-b875-66fb7be4de53", "text": "Igaz", "isCorrect": true}, {"id": "eb585f52-0248-403a-97